25	/**
26	 An Evaluator tests if an element (or a node) meets the selector's requirements. Obtain an evaluator for a given CSS selector
27	 with {@link Selector#evaluatorOf(String css)}. If you are executing the same selector on many elements (or documents), it
28	 can be more efficient to compile and reuse an Evaluator than to reparse the selector on each invocation of select().
29	 <p>Evaluators are thread-safe and may be used concurrently across multiple documents.</p>
30	 */
31	public abstract class Evaluator {
32	    protected Evaluator() {
33	    }
34	
35	    /**
36	     Provides a Predicate for this Evaluator, matching the test Element.
37	     * @param root the root Element, for match evaluation
38	     * @return a predicate that accepts an Element to test for matches with this Evaluator
39	     * @since 1.17.1
40	     */
41	    public Predicate<Element> asPredicate(Element root) {
42	        return element -> matches(root, element);
43	    }
