21	/**
22	 * Parses a CSS selector into an Evaluator tree.
23	 */
24	public class QueryParser implements AutoCloseable {
25	    private final static char[] Combinators = {'>', '+', '~'}; // ' ' is also a combinator, but found implicitly
26	    private final static String[] AttributeEvals = new String[]{"=", "!=", "^=", "$=", "*=", "~="};
27	    private final static char[] SequenceEnders = {',', ')'};
