61	    /**
62	     Parse the query. We use this simplified expression of the grammar:
63	     <pre>
64	     SelectorGroup   ::= Selector (',' Selector)*
65	     Selector        ::= [ Combinator ] SimpleSequence ( Combinator SimpleSequence )*
66	     SimpleSequence  ::= [ TypeSelector ] ( ID | Class | Attribute | Pseudo )*
67	     Pseudo           ::= ':' Name [ '(' SelectorGroup ')' ]
68	     Combinator      ::= S+         // descendant (whitespace)
69	     | '>'       // child
70	     | '+'       // adjacent sibling
71	     | '~'       // general sibling
72	     </pre>
73	
74	     See <a href="https://www.w3.org/TR/selectors-4/#grammar">selectors-4</a> for the real thing
75	     */
76	    Evaluator parse() {
77	        Evaluator eval = parseSelectorGroup();
78	        tq.consumeWhitespace();
79	        if (!tq.isEmpty())
80	            throw new Selector.SelectorParseException("Could not parse query '%s': unexpected token at '%s'", query, tq.remainder());
81	        return eval;
