84	    Evaluator parseSelectorGroup() {
85	        // SelectorGroup. Into an Or if > 1 Selector
86	        Evaluator left = parseSelector();
87	        while (tq.matchChomp(',')) {
88	            Evaluator right = parseSelector();
89	            left = or(left, right);
90	        }
91	        return left;
92	    }
