import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import java.util.List;

public class test_fix {
    public static void main(String[] args) {
        // Test case 1: Contains selector with spaces
        String html1 = "<body><article xxx=\"xpaywalled\"></article></body>";
        Document doc1 = Jsoup.parse(html1);

        // This should NOT match (attribute value is "xpaywalled", not contains " paywalled ")
        List<Element> result1 = doc1.select("article[xxx*=\" paywalled \"]");
        System.out.println("Test 1 - [xxx*=\" paywalled \"]: " + (result1.isEmpty() ? "PASS (no match)" : "FAIL (matched)"));

        // This should match (attribute value contains "paywalled")
        List<Element> result2 = doc1.select("article[xxx*=\"paywalled\"]");
        System.out.println("Test 2 - [xxx*=\"paywalled\"]: " + (!result2.isEmpty() ? "PASS (matched)" : "FAIL (no match)"));

        // Test case 2: Exact match with spaces
        String html2 = "<body><div data=\"exact\"></div><div data=\" exact \"></div></body>";
        Document doc2 = Jsoup.parse(html2);

        // Should not match because attribute is "exact", not " exact "
        List<Element> result3 = doc2.select("div[data=\" exact \"]");
        System.out.println("Test 3 - [data=\" exact \"]: " + (result3.isEmpty() ? "PASS (no match)" : "FAIL (matched)"));

        // Should match "exact"
        List<Element> result4 = doc2.select("div[data=\"exact\"]");
        System.out.println("Test 4 - [data=\"exact\"]: " + (result4.size() == 1 ? "PASS (1 match)" : "FAIL (" + result4.size() + " matches)"));

        // Test case 3: Starts-with selector with spaces
        String html3 = "<body><p attr=\" start\"></p><p attr=\"start\"></p></body>";
        Document doc3 = Jsoup.parse(html3);

        // Should match the first one (starts with " start")
        List<Element> result5 = doc3.select("p[attr^=\" start\"]");
        System.out.println("Test 5 - [attr^=\" start\"]: " + (result5.size() == 1 ? "PASS (1 match)" : "FAIL (" + result5.size() + " matches)"));

        // Should match the second one (starts with "start")
        List<Element> result6 = doc3.select("p[attr^=\"start\"]");
        System.out.println("Test 6 - [attr^=\"start\"]: " + (result6.size() == 1 ? "PASS (1 match)" : "FAIL (" + result6.size() + " matches)"));

        // Test case 4: Empty attribute values
        String html4 = "<body><div data=\"\"></div><div data=\"nonempty\"></div></body>";
        Document doc4 = Jsoup.parse(html4);

        try {
            // Should match the empty attribute
            List<Element> result7 = doc4.select("div[data='']");
            System.out.println("Test 7 - [data='']: " + (result7.size() == 1 ? "PASS (1 match)" : "FAIL (" + result7.size() + " matches)"));
        } catch (Exception e) {
            System.out.println("Test 7 - [data='']: FAIL (exception: " + e.getMessage() + ")");
        }
    }
}

